{% extends "templates/print/ph_basis.html" %}
{% block titel %}Stellenanzeige {{ doc.titel }}{% endblock %}
{% block kopfrechts %}Stellenanzeige<br>{% if doc.veroeffentlicht %}ab {{ ph_datum(doc.veroeffentlicht) }}{% endif %}{% if doc.gueltig_bis %}<br>gültig bis {{ ph_datum(doc.gueltig_bis) }}{% endif %}{% endblock %}
{% block css %}
  .ph-aushang h1 { font-size: 20pt; margin-bottom: 1mm; }
  .ph-aushang .ph-meta { color: var(--ph-grau); font-size: 9.5pt; margin-bottom: 6mm; }
  .ph-aushang ul { margin: 1mm 0 4mm 5mm; padding: 0; }
  .ph-aushang li { margin-bottom: 1mm; }
  .ph-entgelt { border: 1px solid var(--ph-linie); padding: 3mm 4mm; margin: 5mm 0; background: var(--ph-sand); }
  .ph-bewerben { margin-top: 6mm; font-size: 10pt; }
{% endblock %}
{% block inhalt %}
{% set einst = frappe.get_cached_doc("PH Personal Einstellungen") %}
<div class="ph-aushang">
  <h1>{{ doc.titel }}</h1>
  <div class="ph-meta">
    {{ _(doc.kategorie) }} · {{ _(doc.beschaeftigungsart) }} · Beginn {{ doc.start or "ab sofort" }}
    {% if (doc.positionen_anzahl or 1) > 1 %} · {{ doc.positionen_anzahl }} Stellen{% endif %}
    · {{ doc.standort or einst.standort }}
  </div>
  {% if doc.status != "Aktiv" %}<p class="ph-hinweis"><b>Entwurf</b> – Status {{ _(doc.status) }}. Nicht veröffentlicht.</p>{% endif %}
  {% if not doc.entgelt_vollstaendig %}<p class="ph-hinweis" style="color:#b91c1c"><b>Entgeltangabe fehlt</b> – nach § 9 Abs 2 GlBG nicht veröffentlichbar.</p>{% endif %}

  {% if doc.stellenbeschreibung %}<p>{{ doc.stellenbeschreibung | e | replace("\n", "<br>") }}</p>{% endif %}

  {% if doc.aufgaben_de %}<h2>Ihre Aufgaben</h2><ul>{% for z in doc.aufgaben_de %}<li>{{ z.responsibility }}</li>{% endfor %}</ul>{% endif %}
  {% if doc.anforderungen_de %}<h2>Ihr Profil</h2><ul>{% for z in doc.anforderungen_de %}<li>{{ z.anforderungen }}</li>{% endfor %}</ul>{% endif %}
  {% if doc.arbeitszeit_de %}<h2>Arbeitszeit</h2><ul>{% for z in doc.arbeitszeit_de.splitlines() if z.strip() %}<li>{{ z }}</li>{% endfor %}</ul>{% endif %}
  {% if doc.leistungen_de %}<h2>Wir bieten</h2><ul>{% for z in doc.leistungen_de %}<li>{{ z.benefit }}</li>{% endfor %}</ul>{% endif %}

  <div class="ph-entgelt">
    <h2 style="margin-top:0">Entgelt</h2>
    {% if doc.entgelt_text %}<p style="margin:0">{{ doc.entgelt_text }}</p>{% else %}<p style="margin:0;color:#b91c1c">Kollektivvertragliches Mindestentgelt und Überzahlungsbereitschaft noch nicht erfasst.</p>{% endif %}
  </div>

  <div class="ph-bewerben">
    <h2>Bewerbung</h2>
    <p>Wir freuen uns auf Ihre Bewerbung mit Lebenslauf an <b>{{ doc.bewerbung_email or einst.bewerbung_email }}</b>
    {% if doc.ansprechpartner %} – Ansprechperson: {{ frappe.db.get_value("User", doc.ansprechpartner, "full_name") }}{% endif %}.<br>
    Online: {{ doc.website_url }}</p>
    <p style="font-size:8.5pt;color:#6b7280">Wie wir Bewerbungsdaten verarbeiten, erklärt unsere Datenschutzerklärung unter platzhirsch.studio/datenschutz. Unterlagen werden nach Abschluss des Verfahrens innerhalb der gesetzlichen Fristen gelöscht.</p>
  </div>
</div>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Bewerbung {{ doc.name }}{% endblock %}
{% block kopfrechts %}Bewerbung {{ doc.name }}<br>Eingang {{ ph_datum(doc.eingang) }}<br>Status {{ _(doc.status) }}{% endblock %}
{% block inhalt %}
<h1>{{ doc.titel }}</h1>
<div class="ph-feld"><b>Stelle</b> {{ doc.stelle_titel or "Initiativbewerbung" }}</div>
<div class="ph-feld"><b>Name</b> {{ doc.anrede or "" }} {{ doc.vorname or "" }} {{ doc.nachname }}</div>
<div class="ph-feld"><b>E-Mail</b> {{ doc.email or "–" }}</div>
<div class="ph-feld"><b>Telefon</b> {{ doc.telefon or "–" }}</div>
{% if doc.plz_ort %}<div class="ph-feld"><b>Ort</b> {{ doc.plz_ort }}</div>{% endif %}
{% if doc.verfuegbar_ab %}<div class="ph-feld"><b>Verfügbar ab</b> {{ ph_datum(doc.verfuegbar_ab) }}</div>{% endif %}
<div class="ph-feld"><b>Quelle</b> {{ doc.quelle }}{% if doc.sprache %} · {{ doc.sprache }}{% endif %}</div>
<div class="ph-feld"><b>Zuständig</b> {{ frappe.db.get_value("User", doc.zugewiesen_an, "full_name") if doc.zugewiesen_an else "–" }}</div>

{% if doc.anschreiben %}<h2>Anschreiben</h2><div>{{ doc.anschreiben }}</div>{% endif %}

<h2>Unterlagen</h2>
{% if doc.unterlagen %}
<table class="ph-tabelle"><thead><tr><th>Art</th><th>Bezeichnung</th><th class="zahl">Hochgeladen</th><th class="zahl">KB</th></tr></thead><tbody>
{% for u in doc.unterlagen %}<tr><td>{{ u.art }}</td><td>{{ u.bezeichnung or u.datei }}</td><td class="zahl">{{ ph_datum(u.hochgeladen_am) }}</td><td class="zahl">{{ u.groesse_kb or "" }}</td></tr>{% endfor %}
</tbody></table>
{% else %}<p>Keine Unterlagen.</p>{% endif %}

<h2>Verlauf</h2>
<table class="ph-tabelle"><tbody>
<tr><td>Eingang</td><td class="zahl">{{ ph_datum(doc.eingang) }}</td></tr>
{% if doc.gesichtet_am %}<tr><td>Gesichtet</td><td class="zahl">{{ ph_datum(doc.gesichtet_am) }}</td></tr>{% endif %}
{% if doc.gespraech_am %}<tr><td>Erstes Gespräch</td><td class="zahl">{{ ph_datum(doc.gespraech_am) }}</td></tr>{% endif %}
{% if doc.angebot_am %}<tr><td>Angebot</td><td class="zahl">{{ ph_datum(doc.angebot_am) }}</td></tr>{% endif %}
{% if doc.entschieden_am %}<tr><td>Entscheidung ({{ _(doc.status) }})</td><td class="zahl">{{ ph_datum(doc.entschieden_am) }} · {{ doc.durchlauf_tage }} Tage</td></tr>{% endif %}
{% if doc.loeschfrist %}<tr><td>Löschfrist</td><td class="zahl">{{ ph_datum(doc.loeschfrist) }}</td></tr>{% endif %}
</tbody></table>

<div style="margin-top:8mm;border:1px solid var(--ph-linie);padding:3mm 4mm;min-height:30mm">
  <b style="font-size:8.5pt;color:#6b7280;text-transform:uppercase;letter-spacing:.04em">Notizen (handschriftlich, nach dem Gespräch in die Bewertung übertragen und vernichten)</b>
</div>
<p class="ph-hinweis">Interner Ausdruck. Enthält personenbezogene Daten – nach Gebrauch vernichten (Aufbewahrung nur im Backoffice, Löschfrist läuft automatisch).</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set einst = frappe.get_cached_doc("PH Personal Einstellungen") %}
{% block titel %}Absage {{ doc.name }}{% endblock %}
{% block kopfrechts %}{{ firma.ort }}, {{ ph_datum(doc.absage_gesendet_am or frappe.utils.nowdate()) }}{% endblock %}
{% block css %} .ph-brief p { margin: 0 0 3mm; } .ph-anschrift { margin: 6mm 0 12mm; line-height: 1.4; } {% endblock %}
{% block inhalt %}
<div class="ph-brief">
  <div class="ph-absender">{{ firma.firmenname }} · {{ firma.strasse }} · {{ firma.plz }} {{ firma.ort }}</div>
  <div class="ph-anschrift">{{ doc.anrede or "" }}<br>{{ doc.vorname or "" }} {{ doc.nachname }}<br>{{ doc.plz_ort or "" }}</div>
  <h1>Ihre Bewerbung{% if doc.stelle_titel %} als {{ doc.stelle_titel }}{% endif %}</h1>
  <p>{% if doc.anrede == "Frau" %}Sehr geehrte Frau {{ doc.nachname }},{% elif doc.anrede == "Herr" %}Sehr geehrter Herr {{ doc.nachname }},{% else %}Guten Tag {{ doc.vorname or "" }} {{ doc.nachname }},{% endif %}</p>
  {{ einst.absage_text }}
  <p>Mit freundlichen Grüßen</p>
  <p style="margin-top:10mm">{{ firma.geschaeftsfuehrung or firma.marke }}<br><span style="color:#6b7280">{{ firma.kurzname or firma.firmenname }}</span></p>
</div>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set einst = frappe.get_cached_doc("PH Personal Einstellungen") %}
{% set stelle = frappe.get_cached_doc("PH Stelle", doc.stelle) if doc.stelle else None %}
{% block titel %}Zusage {{ doc.name }}{% endblock %}
{% block kopfrechts %}{{ firma.ort }}, {{ ph_datum(doc.zusage_gesendet_am or frappe.utils.nowdate()) }}{% endblock %}
{% block css %} .ph-brief p { margin: 0 0 3mm; } .ph-anschrift { margin: 6mm 0 12mm; line-height: 1.4; } {% endblock %}
{% block inhalt %}
<div class="ph-brief">
  <div class="ph-absender">{{ firma.firmenname }} · {{ firma.strasse }} · {{ firma.plz }} {{ firma.ort }}</div>
  <div class="ph-anschrift">{{ doc.anrede or "" }}<br>{{ doc.vorname or "" }} {{ doc.nachname }}<br>{{ doc.plz_ort or "" }}</div>
  <h1>Zusage{% if doc.stelle_titel %}: {{ doc.stelle_titel }}{% endif %}</h1>
  <p>{% if doc.anrede == "Frau" %}Sehr geehrte Frau {{ doc.nachname }},{% elif doc.anrede == "Herr" %}Sehr geehrter Herr {{ doc.nachname }},{% else %}Guten Tag {{ doc.vorname or "" }} {{ doc.nachname }},{% endif %}</p>
  {{ einst.zusage_text }}
  {% if stelle %}
  <table class="ph-tabelle" style="margin:4mm 0">
    <tbody>
      <tr><td>Position</td><td>{{ stelle.titel }}</td></tr>
      <tr><td>Beschäftigungsausmaß</td><td>{{ _(stelle.beschaeftigungsart) }}</td></tr>
      <tr><td>Arbeitsort</td><td>{{ stelle.standort or einst.standort }}</td></tr>
      {% if stelle.entgelt_text %}<tr><td>Entgelt (Kollektivvertrag)</td><td>{{ stelle.entgelt_text }}</td></tr>{% endif %}
      {% if doc.mitarbeiter %}<tr><td>Eintritt</td><td>{{ ph_datum(frappe.db.get_value("PH Mitarbeiter", doc.mitarbeiter, "eintritt")) }}</td></tr>{% endif %}
    </tbody>
  </table>
  {% endif %}
  <p>Mit freundlichen Grüßen</p>
  <p style="margin-top:10mm">{{ firma.geschaeftsfuehrung or firma.marke }}<br><span style="color:#6b7280">{{ firma.kurzname or firma.firmenname }}</span></p>
  <p style="font-size:8pt;color:#6b7280;margin-top:8mm">Dienstzettel (§ 2 AVRAG) bzw. Dienstvertrag folgen gesondert; dieser Brief begründet kein Dienstverhältnis.</p>
</div>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set heute = frappe.utils.getdate(doc.zeitnachweis_monat or frappe.utils.nowdate()) %}
{% set m = frappe.call("ph_personal.api.monatsuebersicht", mitarbeiter=doc.name, jahr=heute.year, monat=heute.month) %}
{% block titel %}Zeitnachweis {{ doc.titel }} {{ "%02d" % m.monat }}/{{ m.jahr }}{% endblock %}
{% block kopfrechts %}Zeitnachweis<br>{{ "%02d" % m.monat }}/{{ m.jahr }}<br>{{ doc.name }}{% endblock %}
{% block css %} .ph-summen td { padding: 1.5mm 3mm; } .ph-summen b { font-size: 12pt; } {% endblock %}
{% block inhalt %}
<h1>Zeitnachweis {{ doc.titel }}</h1>
<div class="ph-feld"><b>Zeitraum</b> {{ ph_datum(m.von) }} – {{ ph_datum(m.bis) }} · {{ m.arbeitstage|int }} Arbeitstage · {{ m.wochenstunden }} h/Woche</div>
<div class="ph-feld"><b>Rolle</b> {{ _(doc.rolle_intern) }}{% if doc.beschaeftigungsart %} · {{ _(doc.beschaeftigungsart) }}{% endif %}</div>

<table class="ph-tabelle ph-summen" style="width:auto;margin:4mm 0 6mm">
  <tr><td>Soll</td><td class="zahl"><b>{{ m.soll_text }}</b></td><td>Ist (gebucht)</td><td class="zahl"><b>{{ m.ist_text }}</b></td><td>Gutschrift Abwesenheit</td><td class="zahl"><b>{{ m.gutschrift_text }}</b></td><td>Saldo</td><td class="zahl"><b style="color:{{ '#15803d' if m.saldo_min >= 0 else '#b91c1c' }}">{{ m.saldo_text }}</b></td></tr>
</table>
<p style="font-size:9pt;color:#6b7280">Abwesenheiten (Arbeitstage): Urlaub {{ m.urlaub_tage }} · Krankenstand {{ m.krank_tage }} · Sonstige {{ m.sonstige_tage }}{% if m.offen %} · <span style="color:#b91c1c">{{ m.offen }} offene Buchung(en) ohne „Gehen“</span>{% endif %}</p>

<table class="ph-tabelle">
  <thead><tr><th>Datum</th><th>Art</th><th class="zahl">Kommen</th><th class="zahl">Gehen</th><th class="zahl">Pause</th><th class="zahl">Netto</th><th>Projekt / Notiz</th></tr></thead>
  <tbody>
  {% for t in m.tage %}
    <tr><td>{{ ph_datum(t.datum) }}</td><td>{{ _(t.art) }}</td><td class="zahl">{{ t.kommen }}</td><td class="zahl">{{ t.gehen or "–" }}</td><td class="zahl">{{ t.pause_min or 0 }}</td><td class="zahl">{{ t.dauer_text or "" }}</td><td>{{ t.projekt_referenz or "" }}</td></tr>
  {% else %}
    <tr><td colspan="7">Keine Buchungen in diesem Monat.</td></tr>
  {% endfor %}
  </tbody>
  <tfoot><tr class="ph-summe"><td colspan="5">Summe</td><td class="zahl">{{ m.ist_text }}</td><td></td></tr></tfoot>
</table>

<table style="width:100%;margin-top:14mm;font-size:9pt"><tr>
  <td style="width:50%;padding-right:10mm"><div style="border-top:1px solid #30373e;padding-top:2mm">Datum, Unterschrift Mitarbeiter/in</div></td>
  <td style="width:50%"><div style="border-top:1px solid #30373e;padding-top:2mm">Datum, Unterschrift Leitung</div></td>
</tr></table>
<p class="ph-hinweis" style="margin-top:8mm">Aufzeichnung nach § 26 AZG. Erfassung ohne Prüfung von Höchstgrenzen, Ruhezeiten und Zuschlägen – diese prüft die Lohnverrechnung.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Abwesenheit {{ doc.name }}{% endblock %}
{% block kopfrechts %}{{ firma.ort }}, {{ ph_datum(doc.genehmigt_am or frappe.utils.nowdate()) }}<br>{{ doc.name }}{% endblock %}
{% block css %} .ph-tab td { padding: 1.5mm 2mm; border-bottom: 0.2mm solid #e5e7eb; } .ph-tab td:first-child { color: #6b7280; width: 45mm; } {% endblock %}
{% block inhalt %}
<h1>{% if doc.status == "Genehmigt" %}Bestätigung{% else %}Antrag{% endif %} {{ doc.art }}</h1>
<table class="ph-tab">
  <tr><td>Mitarbeiter:in</td><td>{{ doc.mitarbeiter_name }}</td></tr>
  <tr><td>Zeitraum</td><td>{{ ph_datum(doc.von) }}{% if doc.bis != doc.von %} – {{ ph_datum(doc.bis) }}{% endif %}{% if doc.halbtags %} (halber Tag){% endif %}</td></tr>
  <tr><td>Arbeitstage</td><td>{{ doc.tage }}{% if doc.stunden %} · {{ doc.stunden }} Stunden{% endif %}</td></tr>
  {% if doc.unterbrechung_von %}<tr><td>Unterbrochen</td><td>{{ ph_datum(doc.unterbrechung_von) }} – {{ ph_datum(doc.unterbrechung_bis) }} (Krankenstand, § 5 UrlG – nicht als Urlaub gezählt)</td></tr>{% endif %}
  <tr><td>Status</td><td>{{ doc.status }}{% if doc.genehmigt_am %} am {{ ph_datum(doc.genehmigt_am) }}{% endif %}</td></tr>
  {% if doc.vertretung %}<tr><td>Vertretung</td><td>{{ frappe.db.get_value("PH Mitarbeiter", doc.vertretung, "titel") }}</td></tr>{% endif %}
  {% if doc.art == "Urlaub" %}
  <tr><td>Urlaubskonto</td><td>Anspruch Urlaubsjahr {{ doc.urlaub_anspruch }} Tage · Rest nach diesem Urlaub {{ doc.urlaub_rest }} Tage{% if doc.urlaub_verjaehrung %} · ältester Rest verjährt am {{ ph_datum(doc.urlaub_verjaehrung) }} (§ 4 Abs 5 UrlG){% endif %}</td></tr>
  {% if doc.tage_je_urlaubsjahr %}<tr><td>Tage je Urlaubsjahr</td><td>{{ doc.tage_je_urlaubsjahr | replace("\n", "<br>") }}</td></tr>{% endif %}
  {% endif %}
  {% if doc.status == "Abgelehnt" and doc.ablehnungsgrund %}<tr><td>Begründung</td><td>{{ doc.ablehnungsgrund }}</td></tr>{% endif %}
</table>
<p style="margin-top:12mm">Für {{ firma.kurzname or firma.firmenname }}: ______________________ &nbsp;&nbsp; Mitarbeiter:in: ______________________</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Dienstplan KW {{ doc.kalenderwoche }}/{{ doc.jahr }}{% endblock %}
{% block kopfrechts %}KW {{ doc.kalenderwoche }}/{{ doc.jahr }}<br>{{ ph_datum(doc.woche_von) }} – {{ ph_datum(doc.woche_bis) }}<br>{{ "Veröffentlicht" if doc.status == "Veroeffentlicht" else "Entwurf" }}{% endblock %}
{% block css %} .ph-plan { width: 100%; border-collapse: collapse; font-size: 8.5pt; } .ph-plan th, .ph-plan td { border: 0.2mm solid #d1d5db; padding: 1.2mm; vertical-align: top; } .ph-plan th { background: #f5f3f0; } .ph-plan .frei { color: #9ca3af; } {% endblock %}
{% block inhalt %}
{% set tage = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"] %}
{% set personen = [] %}
{% for z in doc.schichten %}{% if z.mitarbeiter_name not in personen %}{% set _ = personen.append(z.mitarbeiter_name) %}{% endif %}{% endfor %}
<h1>Dienstplan</h1>
<table class="ph-plan">
  <thead><tr><th>Person</th>{% for i in range(7) %}<th>{{ tage[i] }} {{ frappe.utils.formatdate(frappe.utils.add_days(doc.woche_von, i), "dd.MM.") }}</th>{% endfor %}<th>Stunden</th></tr></thead>
  <tbody>
  {% for p in personen %}
    {% set ns = namespace(summe=0) %}
    <tr><td>{{ p }}</td>
    {% for i in range(7) %}
      {% set tag = frappe.utils.getdate(frappe.utils.add_days(doc.woche_von, i)) %}
      <td>{% for z in doc.schichten if z.mitarbeiter_name == p and frappe.utils.getdate(z.datum) == tag %}{{ (z.beginn|string)[:5] }}–{{ (z.ende|string)[:5] }}<br><span class="frei">{{ z.bereich or "" }}</span>{% set ns.summe = ns.summe + (z.netto_min or 0) %}{% if not loop.last %}<br>{% endif %}{% else %}<span class="frei">–</span>{% endfor %}</td>
    {% endfor %}
    <td>{{ "%.1f" % (ns.summe / 60) }}</td></tr>
  {% endfor %}
  </tbody>
</table>
{% if doc.pruefergebnis and doc.status != "Veroeffentlicht" %}<h2 style="margin-top:6mm">Prüfung</h2><p style="white-space:pre-line;font-size:8.5pt">{{ doc.pruefergebnis }}</p>{% endif %}
<p style="margin-top:6mm;font-size:8pt;color:#6b7280">Ruhezeit mindestens 11 Stunden (AZG § 12), Wochenend-/Wochenruhe 36 Stunden (ARG § 3/§ 4). Änderungen bitte mit der Leitung abstimmen.</p>
{% endblock %}
